FIELD_ORDER=['price','display','processor','ram_storage','camera','battery','charging','audio','anc','features','water_resistance','connectivity','colors','warranty','availability']
FIELD_MAP={'price':'price','display':'display','processor':'processor','ram_storage':'ram_storage','camera':'camera','battery':'battery','charging':'charging','audio':'audio','anc':'anc','features':'features','water_resistance':'water_resistance','connectivity':'connectivity','colors':'colors','warranty':'warranty','availability':'availability'}
# ITRANS transliteration keeps every supported Indian language in Latin script
# when the customer types that language using English letters. The optional
# package is installed through requirements.txt with the project dependencies.
def romanize_response(text, lang):
 try:
  from indic_transliteration import sanscript
  source = {
   "te": sanscript.TELUGU, "hi": sanscript.DEVANAGARI, "mr": sanscript.DEVANAGARI,
   "ta": sanscript.TAMIL, "kn": sanscript.KANNADA, "ml": sanscript.MALAYALAM,
   "bn": sanscript.BENGALI, "gu": sanscript.GUJARATI, "pa": sanscript.GURMUKHI,
  }.get(lang)
  return sanscript.transliterate(text, source, sanscript.ITRANS) if source else text
 except (ImportError, AttributeError, ValueError):
  return text


class NivaChatbot:
 def __init__(self,catalog_path=CATALOG_PATH):
  self.catalog=json.loads(Path(catalog_path).read_text(encoding='utf-8'))
 def products(self,category=None):
  if category:return self.catalog['products'].get(category,[])
  return [p for group in self.catalog['products'].values() for p in group]
 def _find(self,model):
  for cat,items in self.catalog['products'].items():
   for p in items:
    if p['model']==model:return cat,p
  return None,None
 def _value(self,p,key,lang):
  v=p.get(key)
  if v is None and key=='warranty':v=self.catalog['global_warranty']
  if v is None:return None
  if key=='price':return f"₹{v:,}"
  if key=='availability':return T[lang]['status'].get(v,v)
  if isinstance(v,list):return ', '.join(v)
  return str(v)
 def _product_details(self,p,lang,feature=None):
  t=T[lang]; lines=[f"✨ **{p['model']}**"]
  keys=[feature] if feature in FIELD_MAP else FIELD_ORDER
  for k in keys:
   if k in p or k=='warranty':
    val=self._value(p,k,lang)
    if val:lines.append(f"{t.get(k,k.title())}: {val}")
  return '\n'.join(lines)
 def reply(self,message,context=None,manual_language='Auto-detect'):
  ctx=dict(context or {})
  if not isinstance(message,str) or not message.strip():return 'Please enter a message.','en',ctx
  lang=detect_language(message,manual_language)
  if lang not in T:lang='en'
  t=T[lang]
  intent=classify_intent(message,lang)
  cat=identify_category(message,lang,ctx.get('category'))
  model=identify_model(message,self.catalog,ctx.get('model'))
  feature=identify_feature(message,lang)
  order_id=extract_order_id(message)
  if model:
   cat,p=self._find(model);ctx.update({'model':model,'category':cat})
  else:p=None
  if intent=='greeting':ans=t['hello']
  elif intent=='help':ans=t['help']
  elif intent=='models':
   if not cat:ans=t['askcat']
   else:
    names=', '.join(p['model'] for p in self.products(cat))
    ans=f"{t['models'].format(cat=t['categories'][cat])}\n{names}"
    ctx['category']=cat
  elif intent=='warranty' and not p and cat:
   ans=t['allwarranty'].format(cat=t['categories'][cat],value=self.catalog['global_warranty'])
  elif intent=='warranty' and not p and not cat:
   ans=f"{t['allwarranty'].format(cat='Niva products',value=self.catalog['global_warranty'])}"
  elif intent=='returns':ans=t['return']
  elif intent=='refunds' and any(x in message for x in {'te':['రిటర్న్','తిరిగి'],'hi':['वापस','रिटर्न'],'ta':['திரும்ப','ரிட்டர்ன்'],'kn':['ಹಿಂತಿರುಗಿ','ರಿಟರ್ನ್'],'ml':['തിരികെ','റിട്ടേൺ'],'bn':['ফেরত','রিটার্ন'],'mr':['परत','रिटर्न'],'gu':['પરત','રિટર્ન'],'pa':['ਵਾਪਸ','ਰਿਟਰਨ']}.get(lang,[])):
   ans=t['return']+'\n'+t['refund']
  elif intent=='refunds':ans=t['refund']
  elif intent=='payments':ans=t['payments']
  elif intent=='delivery':ans=t['delivery']
  elif intent=='tracking':
   order=self.catalog['sample_orders'].get(order_id) if order_id else None
   if order:ans=t['order'].format(id=order_id,status=order['status'],item=order['item'],date=order['estimated_delivery'])
   else:ans=t['trackask']
  elif intent=='availability' and cat and not p:
   ans=t['stock']+'\n'+'\n'.join(f"• {x['model']}: {t['status'].get(x['availability'],x['availability'])}" for x in self.products(cat))
  elif p:ans=self._product_details(p,lang,feature or (intent if intent in FIELD_MAP else None))
  elif cat:
   ans=t['needmodel'].format(cat=t['categories'][cat])
  else:ans=t['unknown']
  # Preserve the user's writing style: Romanized input receives Romanized output;
  # native-script input continues to receive the native script.
  if is_romanized_input(message, lang):
   ans = romanize_response(ans, lang)
  return ans,lang,ctx
